-- Connection-local, content-revision keyed indexes. No production schema changes.
CREATE TEMP TABLE perf_words AS
 SELECT w.id,w.owner_id,lower(trim(w.word)) AS normalized,/* BASIC_WORD_BEGIN */ CASE WHEN lower(trim(w.word)) IN ('a','ability','able','about','above','accept','accord','account','achieve','across','act','action','activity','actually','add','addition','address','advantage','affect','after','again','against','age','ago','agree','agreement','aim','air','all','allow','almost','alone','along','already','also','although','always','among','amount','analysis','and','animal','another','answer','any','anyone','anything','appear','apply','approach','area','argue','arm','around','arrive','art','article','as','ask','at','attack','attempt','attention','available','average','away','back','bad','bank','base','be','bear','beautiful','because','become','bed','before','begin','behavior','behind','believe','below','benefit','between','big','bit','black','board','body','book','both','boy','break','bring','build','business','but','buy','by','call','campaign','can','capital','car','card','care','carry','case','catch','cause','cell','cent','center','century','certain','certainly','challenge','chance','change','character','charge','check','child','choice','choose','church','city','claim','class','clear','clearly','close','club','college','color','come','comment','common','community','company','compare','complete','computer','concern','condition','consider','contact','contain','continue','contract','control','cost','could','country','couple','course','court','cover','create','culture','current','customer','cut','data','date','day','deal','death','decide','decision','degree','demand','department','depend','describe','design','despite','detail','determine','develop','development','die','difference','different','difficult','direct','director','discuss','discussion','do','doctor','door','down','draw','drink','drive','drop','drug','due','during','each','early','easy','eat','economic','economy','education','effect','effort','either','election','else','employee','end','enjoy','enough','enter','environment','especially','establish','even','evening','event','ever','every','everyone','everything','evidence','exactly','example','exist','expect','experience','explain','eye','face','fact','factor','fail','fall','family','far','fast','father','fear','feature','feel','few','field','fight','figure','film','final','finally','financial','find','fine','finish','fire','firm','first','fit','floor','focus','follow','food','foot','for','force','foreign','forget','form','former','forward','free','friend','from','front','full','function','fund','further','future','gain','game','general','get','girl','give','go','good','government','great','ground','group','grow','growth','guy','half','hand','happen','happy','hard','have','he','head','health','hear','heart','help','here','high','himself','history','hit','hold','holiday','home','hope','hospital','hotel','hour','house','how','however','human','i','idea','if','image','important','improve','in','include','increase','indeed','individual','industry','influence','information','inside','instead','interest','international','interview','into','introduce','involve','issue','it','item','itself','job','join','just','keep','key','kid','kill','kind','know','knowledge','lack','land','language','large','last','late','laugh','law','lead','leader','learn','least','leave','less','let','letter','level','lie','life','light','like','likely','limit','line','link','list','listen','little','live','local','long','look','lose','lot','love','low','machine','main','major','make','man','manage','management','manager','many','mark','market','marry','material','matter','may','maybe','mean','measure','medium','meet','member','mention','method','might','mile','military','mind','minute','miss','model','moment','money','month','more','morning','most','mother','move','movie','much','music','must','myself','name','nation','national','nature','near','nearly','necessary','need','never','new','news','next','nice','night','no','not','note','nothing','notice','now','number','occur','of','off','offer','office','official','often','old','on','once','one','only','open','opinion','opportunity','or','order','organization','other','out','outside','over','own','page','paint','paper','parent','park','part','particular','particularly','party','pass','past','patient','pause','pay','people','per','percent','performance','perhaps','period','person','personal','phone','pick','picture','piece','place','plan','plant','play','player','please','point','police','policy','political','poor','popular','population','position','possible','power','practice','prepare','present','president','press','pretty','price','private','probably','problem','process','produce','product','production','program','project','prove','provide','public','pull','purpose','put','quality','question','quickly','quite','race','raise','range','rate','rather','reach','read','ready','real','realize','really','reason','receive','recent','recently','recognize','record','red','reduce','regard','region','relate','relationship','release','remain','remember','report','represent','require','research','respect','response','rest','result','return','review','right','rise','risk','road','role','room','round','rule','run','sale','same','save','say','school','season','second','section','security','see','seek','seem','sell','send','sense','series','serious','serve','service','set','several','share','she','shop','short','should','show','side','sign','significant','similar','simple','simply','since','single','sit','site','situation','size','skill','small','so','social','society','solution','some','someone','something','sometimes','son','soon','sorry','sort','sound','source','space','speak','special','specific','spend','sport','staff','stage','stand','standard','start','state','statement','station','stay','step','still','stock','stop','store','story','street','strike','strong','structure','student','study','stuff','subject','success','such','suggest','summer','support','suppose','sure','surprise','system','table','take','talk','target','tax','teach','teacher','team','technology','television','tell','term','test','than','thank','that','the','themselves','then','there','therefore','they','thing','think','this','though','through','thus','time','to','today','together','tomorrow','too','top','total','toward','town','trade','train','travel','tree','true','try','turn','type','under','understand','unit','until','up','upon','use','usually','value','various','very','view','visit','voice','vote','wait','walk','wall','want','war','watch','water','way','we','wear','week','well','what','whatever','when','where','whether','which','while','white','who','whole','why','wide','wife','will','win','window','wish','with','within','without','woman','wonder','word','work','worker','world','worry','would','write','wrong','year','yes','yesterday','yet','you','young') THEN 1 WHEN 
        lower(trim(w.word)) IN ('her','hers','herself','him','himself','his','its','itself','me','mine','my','myself','oneself','our','ours','ourselves','their','theirs','them','themself','themselves','these','those','us','whom','whose','your','yours','yourself','yourselves') THEN (EXISTS (SELECT 1 FROM word_senses basic_sense WHERE basic_sense.word_id=w.id AND basic_sense.active=1
        AND basic_sense.learning_enabled=1 AND EXISTS (
            SELECT 1 FROM sense_examples basic_example
            WHERE basic_example.sense_id=basic_sense.id AND basic_example.active=1) AND (lower(trim(basic_sense.part_of_speech)) IN ('代词','限定词','冠词','article','pronoun','personal pronoun','possessive pronoun','reflexive pronoun','relative pronoun','demonstrative pronoun','determiner','possessive determiner','demonstrative determiner')
        OR (lower(trim(w.word)) IN ('whose','these','those')
            AND lower(trim(basic_sense.part_of_speech)) IN ('形容词','adjective'))
        OR (lower(trim(w.word))!='mine'
            AND lower(trim(basic_sense.part_of_speech))='词汇')))
        AND NOT EXISTS (SELECT 1 FROM word_senses basic_sense WHERE basic_sense.word_id=w.id AND basic_sense.active=1
        AND basic_sense.learning_enabled=1 AND EXISTS (
            SELECT 1 FROM sense_examples basic_example
            WHERE basic_example.sense_id=basic_sense.id AND basic_example.active=1) AND NOT (lower(trim(basic_sense.part_of_speech)) IN ('代词','限定词','冠词','article','pronoun','personal pronoun','possessive pronoun','reflexive pronoun','relative pronoun','demonstrative pronoun','determiner','possessive determiner','demonstrative determiner')
        OR (lower(trim(w.word)) IN ('whose','these','those')
            AND lower(trim(basic_sense.part_of_speech)) IN ('形容词','adjective'))
        OR (lower(trim(w.word))!='mine'
            AND lower(trim(basic_sense.part_of_speech))='词汇')))) ELSE 0 END /* BASIC_WORD_END */ AS basic FROM main.words w;
CREATE UNIQUE INDEX temp.perf_words_id ON perf_words(id);
CREATE TEMP TABLE perf_usable(id INTEGER PRIMARY KEY) WITHOUT ROWID;
INSERT OR IGNORE INTO temp.perf_usable
 SELECT us.learning_unit_id FROM main.learning_unit_senses us
 JOIN main.word_senses ds ON ds.id=us.sense_id JOIN main.sense_examples ex ON ex.sense_id=ds.id
 WHERE ds.active=1 AND ds.learning_enabled=1 AND ex.active=1;
