ffice','official','often','old','on','once','one','only','open','opinion','opportunity','or','order','organization','other','out','outside','over','own','page','paint','paper','parent','park','part','particular','particularly','party','pass','past','patient','pause','pay','people','per','percent','performance','perhaps','period','person','personal','phone','pick','picture','piece','place','plan','plant','play','player','please','point','police','policy','political','poor','popular','population','position','possible','power','practice','prepare','present','president','press','pretty','price','private','probably','problem','process','produce','product','production','program','project','prove','provide','public','pull','purpose','put','quality','question','quickly','quite','race','raise','range','rate','rather','reach','read','ready','real','realize','really','reason','receive','recent','recently','recognize','record','red','reduce','regard','region','relate','relationship','release','remain','remember','report','represent','require','research','respect','response','rest','result','return','review','right','rise','risk','road','role','room','round','rule','run','sale','same','save','say','school','season','second','section','security','see','seek','seem','sell','send','sense','series','serious','serve','service','set','several','share','she','shop','short','should','show','side','sign','significant','similar','simple','simply','since','single','sit','site','situation','size','skill','small','so','social','society','solution','some','someone','something','sometimes','son','soon','sorry','sort','sound','source','space','speak','special','specific','spend','sport','staff','stage','stand','standard','start','state','statement','station','stay','step','still','stock','stop','store','story','street','strike','strong','structure','student','study','stuff','subject','success','such','suggest','summer','support','suppose','sure','surprise','system','table','take','talk','target','tax','teach','teacher','team','technology','television','tell','term','test','than','thank','that','the','themselves','then','there','therefore','they','thing','think','this','though','through','thus','time','to','today','together','tomorrow','too','top','total','toward','town','trade','train','travel','tree','true','try','turn','type','under','understand','unit','until','up','upon','use','usually','value','various','very','view','visit','voice','vote','wait','walk','wall','want','war','watch','water','way','we','wear','week','well','what','whatever','when','where','whether','which','while','white','who','whole','why','wide','wife','will','win','window','wish','with','within','without','woman','wonder','word','work','worker','world','worry','would','write','wrong','year','yes','yesterday','yet','you','young') THEN 1 WHEN 
